import time
import sqlite3
from storage import connect

class CircuitBreakerOpenError(RuntimeError):
    """Raised when a call is attempted while the circuit is OPEN and the recovery timeout has not elapsed."""
    pass

class CircuitBreaker:
    def __init__(self, db, failure_threshold=3, recovery_timeout=5.0):
        # ---- Parameter validation ----
        if not isinstance(db, sqlite3.Connection):
            raise ValueError("db must be a sqlite3.Connection instance")
        if isinstance(failure_threshold, bool) or not isinstance(failure_threshold, int) or failure_threshold <= 0:
            raise ValueError("failure_threshold must be a positive integer (bools are not allowed)")
        if isinstance(recovery_timeout, bool) or not isinstance(recovery_timeout, (int, float)) or recovery_timeout <= 0:
            raise ValueError("recovery_timeout must be a positive number (bools are not allowed)")
        self.db = db
        self.failure_threshold = failure_threshold
        self.recovery_timeout = float(recovery_timeout)

    # ---- Helper validation methods ----
    def _validate_service(self, service):
        if not isinstance(service, str) or not service:
            raise ValueError("service must be a non‑empty string")
        return service

    def _now(self, now):
        if now is None:
            return time.time()
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise ValueError("now must be a numeric timestamp (bools are not allowed)")
        return float(now)

    # ---- State retrieval ----
    def state(self, service, now=None):
        """Return the current circuit state for *service*.
        Possible return values: 'CLOSED', 'OPEN', 'HALF_OPEN'.
        """
        service = self._validate_service(service)
        cur = self.db.execute(
            "SELECT state, tripped_at FROM circuit_states WHERE service = ?",
            (service,)
        ).fetchone()
        if not cur:
            return 'CLOSED'
        stored_state, tripped_at = cur
        # If stored as OPEN, check if timeout elapsed to transition to HALF_OPEN lazily
        if stored_state == 'OPEN':
            now_ts = self._now(now)
            if tripped_at is not None and (now_ts - tripped_at) >= self.recovery_timeout:
                # Transition to HALF_OPEN (but defer DB write to call())
                return 'HALF_OPEN'
        return stored_state

    def failure_count(self, service):
        """Return the recorded failure count for *service* (0 if unknown)."""
        service = self._validate_service(service)
        cur = self.db.execute(
            "SELECT failure_count FROM circuit_states WHERE service = ?",
            (service,)
        ).fetchone()
        return cur[0] if cur else 0

    # ---- Core call handling ----
    def call(self, service, func, *args, now=None, **kwargs):
        """Execute *func* respecting circuit‑breaker semantics.
        - If the circuit is OPEN and the recovery timeout has not elapsed, raise ``CircuitBreakerOpenError``.
        - In HALF_OPEN, allow a single probe call; success resets to CLOSED, failure re‑opens.
        - In CLOSED, normal operation; failures are counted and may trip the circuit.
        All state mutations are performed atomically; any DB error rolls back the transaction.
        """
        service = self._validate_service(service)
        if not callable(func):
            raise ValueError("func must be callable")
        now_ts = self._now(now)

        # Fetch current state atomically
        cur = self.db.execute(
            "SELECT state, failure_count, tripped_at FROM circuit_states WHERE service = ?",
            (service,)
        ).fetchone()
        if cur:
            stored_state, failure_cnt, tripped_at = cur
        else:
            stored_state, failure_cnt, tripped_at = 'CLOSED', 0, None

        # Determine effective state considering timeout
        effective_state = stored_state
        if stored_state == 'OPEN':
            if tripped_at is not None and (now_ts - tripped_at) >= self.recovery_timeout:
                effective_state = 'HALF_OPEN'
        # -----------------------------------------------------------------
        # Helper to persist a new row or update existing one within a transaction
        # -----------------------------------------------------------------
        def _persist(state, failure_count, tripped_at_val):
            try:
                with self.db:
                    self.db.execute(
                        "INSERT INTO circuit_states (service, state, failure_count, last_failure_time, tripped_at) "
                        "VALUES (?, ?, ?, ?, ?) "
                        "ON CONFLICT(service) DO UPDATE SET state=excluded.state, "
                        "failure_count=excluded.failure_count, last_failure_time=excluded.last_failure_time, "
                        "tripped_at=excluded.tripped_at",
                        (service, state, failure_count, now_ts, tripped_at_val)
                    )
            except Exception as e:
                # Any DB error rolls back automatically due to context manager
                raise
        # -----------------------------------------------------------------
        # Execute based on effective_state
        # -----------------------------------------------------------------
        if effective_state == 'OPEN':
            # Still in open period
            raise CircuitBreakerOpenError(f"Circuit for service '{service}' is OPEN")

        if effective_state == 'HALF_OPEN':
            # Allow a single probe
            try:
                result = func(*args, **kwargs)
            except Exception as exc:
                # Probe failed: re‑open circuit
                _persist('OPEN', self.failure_threshold, now_ts)
                raise exc
            else:
                # Probe succeeded: reset circuit
                _persist('CLOSED', 0, None)
                return result

        # CLOSED state handling
        try:
            result = func(*args, **kwargs)
        except Exception as exc:
            # Record failure
            new_failure_cnt = failure_cnt + 1
            if new_failure_cnt >= self.failure_threshold:
                # Trip circuit to OPEN
                _persist('OPEN', new_failure_cnt, now_ts)
            else:
                # Stay CLOSED but update count and last_failure_time
                _persist('CLOSED', new_failure_cnt, None)
            raise exc
        else:
            # Success: reset failure count if needed
            if failure_cnt != 0:
                _persist('CLOSED', 0, None)
            return result
